    adcs_quat_t qn;
    adcs_mat3_t c_bi, c_bi_t, tmp;
    size_t i, j;
    int finite_ok;

    if ((q_bi == NULL) || (covariance_i == NULL) || (covariance_b == NULL)) {
        if (covariance_b != NULL) {
            for (i = 0; i < 3; i++)
                for (j = 0; j < 3; j++)
                    covariance_b->m[i][j] = 0.0;
        }
        return ADCS_E_NULL;
    }

    finite_ok = isfinite(q_bi->w) && isfinite(q_bi->x) && isfinite(q_bi->y) && isfinite(q_bi->z);
    for (i = 0; i < 3 && finite_ok; i++)
        for (j = 0; j < 3 && finite_ok; j++)
            if (!isfinite(covariance_i->m[i][j]))
                finite_ok = 0;

    if (!finite_ok) {
        for (i = 0; i < 3; i++)
            for (j = 0; j < 3; j++)
                covariance_b->m[i][j] = 0.0;
        return ADCS_E_RANGE;
    }

    if (adcs_quat_normalize(q_bi, &qn) != ADCS_OK) {
        for (i = 0; i < 3; i++)
            for (j = 0; j < 3; j++)
                covariance_b->m[i][j] = 0.0;
        return ADCS_E_DEGENERATE;
    }

    c_bi = adcs_quat_to_dcm_bi(&qn);
    c_bi_t = adcs_mat3_transpose(&c_bi);
    tmp = adcs_mat3_mul(&c_bi, covariance_i);
    *covariance_b = adcs_mat3_mul(&tmp, &c_bi_t);

    return ADCS_OK;
}

